<script>
/* ============================================================
   Deck controller. Slides are declared as data below so the
   content stays readable and editable in one place — the same
   reason the pricing engine is a pure function of evidence.
   ============================================================ */
class Deck{
  constructor(){
    this.slides=[...document.querySelectorAll('.slide')];
    this.i=0;
    this.buildDots();
    this.observe();
    this.bind();
    this.slides[0]?.classList.add('visible');
  }
  buildDots(){
    const n=document.getElementById('dots');
    this.slides.forEach((s,i)=>{
      const b=document.createElement('button');
      b.setAttribute('aria-label','Slide '+(i+1));
      b.onclick=()=>this.go(i);
      n.appendChild(b);
    });
    this.dots=[...n.children];
    this.mark(0);
  }
  /* Intersection Observer drives both the reveal animation and the
     progress chrome, so there is one source of "which slide are we on". */
  observe(){
    const io=new IntersectionObserver(es=>{
      es.forEach(e=>{
        if(e.isIntersecting){
          e.target.classList.add('visible');
          const i=this.slides.indexOf(e.target);
          if(i>-1){this.i=i;this.mark(i);}
        }
      });
    },{threshold:.55});
    this.slides.forEach(s=>io.observe(s));
  }
  mark(i){
    this.dots.forEach((d,j)=>d.setAttribute('aria-current',j===i?'true':'false'));
    document.getElementById('progress').style.width=((i+1)/this.slides.length*100)+'%';
  }
  go(i){
    i=Math.max(0,Math.min(this.slides.length-1,i));
    this.slides[i].scrollIntoView({behavior:'smooth'});
  }
  bind(){
    addEventListener('keydown',e=>{
      if(['ArrowRight','ArrowDown','PageDown',' '].includes(e.key)){e.preventDefault();this.go(this.i+1);}
      if(['ArrowLeft','ArrowUp','PageUp'].includes(e.key)){e.preventDefault();this.go(this.i-1);}
      if(e.key==='Home'){e.preventDefault();this.go(0);}
      if(e.key==='End'){e.preventDefault();this.go(this.slides.length-1);}
    });
    let y0=null;
    addEventListener('touchstart',e=>y0=e.touches[0].clientY,{passive:true});
    addEventListener('touchend',e=>{
      if(y0===null)return;
      const dy=y0-e.changedTouches[0].clientY;
      if(Math.abs(dy)>60)this.go(this.i+(dy>0?1:-1));
      y0=null;
    },{passive:true});
  }
}
addEventListener('DOMContentLoaded',()=>new Deck());
</script>

