const { chromium } = require('playwright-core');
const path = require('path');

const DECK   = process.argv[2];
const OUTDIR = process.argv[3];
const W = 1920, H = 1080, SCALE = 2;
// .reveal is a .55s transition with up to .45s of nth-child stagger -> ~1.0s to
// settle. Buffer generously; a half-drawn slide in a PDF is unfixable later.
const SETTLE_MS = 1900;
const FIRST_SLIDE_EXTRA = 900;   // fonts + the first figure decode

(async () => {
  const browser = await chromium.launch({
    executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
    args: ['--force-color-profile=srgb', '--font-render-hinting=none'],
  });
  const page = await browser.newPage({
    viewport: { width: W, height: H }, deviceScaleFactor: SCALE,
  });
  await page.goto('file://' + DECK, { waitUntil: 'load' });

  // fonts and every image fully decoded before we screenshot anything
  await page.evaluate(() => document.fonts.ready);
  await page.evaluate(async () => {
    await Promise.all([...document.images]
      .filter(i => !i.complete)
      .map(i => new Promise(r => { i.onload = i.onerror = r; })));
  });

  // kill the interactive chrome and smooth scrolling: both are artefacts of a
  // live deck and only cost fidelity in a printed one
  await page.addStyleTag({ content: `
    html { scroll-behavior: auto !important; }
    .hint, .dots { display: none !important; }
  `});

  const n = await page.evaluate(() => document.querySelectorAll('.slide').length);
  console.log(`slides: ${n}`);
  await page.waitForTimeout(FIRST_SLIDE_EXTRA);

  const files = [];
  for (let i = 0; i < n; i++) {
    await page.evaluate((idx) => {
      const s = document.querySelectorAll('.slide')[idx];
      s.scrollIntoView({ block: 'start', behavior: 'auto' });
      s.classList.add('visible');           // belt and braces: don't rely on the IO
    }, i);
    await page.waitForTimeout(SETTLE_MS);   // let the reveal transitions finish
    const f = path.join(OUTDIR, `slide-${String(i + 1).padStart(2, '0')}.png`);
    await page.screenshot({ path: f });
    files.push(f);
    console.log(`  captured ${i + 1}/${n}`);
  }
  await browser.close();
  console.log('done');
})().catch(e => { console.error(e); process.exit(1); });
